/**
 * Private paging helpers shared by the repositories in this directory.
 *
 * Not part of the public data-access surface — repositories re-export nothing
 * from here. Keyset (cursor) pagination is expressed as a row-value comparison
 * so a page boundary is stable even when two rows share a `created_at`.
 */
import { sql } from "drizzle-orm";
import { decodeCursor, encodeCursor } from "./base-repository";
import { makePage } from "@/types/common";
import type { Page } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return sql`(${sort.sortColumn}, ${sort.idColumn}) < (${decoded.sortValue}, ${decoded.id})`;
}

/** SQLite tolerates a `LIMIT` of `n + 1`; that extra row is the has-more probe. */
export function probeLimit(limit: number): number {
  return Math.max(1, Math.min(limit, 100)) + 1;
}

/**
 * Turns an over-fetched row array into a `Page`, dropping the probe row and
 * deriving the next cursor from the last row that survived.
 */
export function toPage<TRow, TOut>(
  rows: readonly TRow[],
  limit: number,
  total: number,
  map: (row: TRow) => TOut,
  cursorOf: (row: TRow) => { id: string; sortValue: string },
): Page<TOut> {
  const capped = Math.max(1, Math.min(limit, 100));
  const hasMore = rows.length > capped;
  const visible = hasMore ? rows.slice(0, capped) : rows;
  const last = visible.at(-1);

  const nextCursor =
    hasMore && last
      ? encodeCursor(cursorOf(last).id, cursorOf(last).sortValue)
      : null;

  return makePage(visible.map(map), nextCursor, total);
}

/** Drops the `undefined` slots so `and(...)` never sees a hole. */
export function compact(
  ...predicates: readonly (SQL | undefined)[]
): readonly SQL[] {
  return predicates.filter((value): value is SQL => value !== undefined);
}

/**
 * Presentation helpers for the audit trail.
 *
 * `ActivityEvent.summary` is written by the service layer and is authoritative;
 * these helpers only supply the verb chip and the day grouping the feed and the
 * per-issue panel both render, so the two views never disagree about what a
 * day boundary is.
 */
import type { ActivityAction, ActivityEvent, ActivityGroup } from "@/types/activity";

export const ACTIVITY_LABELS: Readonly<Record<ActivityAction, string>> = {
  "organization.updated": "updated the organization",
  "project.created": "created a project",
  "project.updated": "updated a project",
  "project.archived": "archived a project",
  "project.restored": "restored a project",
  "issue.created": "created an issue",
  "issue.updated": "updated an issue",
  "issue.status_changed": "changed status",
  "issue.assigned": "assigned an issue",
  "issue.archived": "archived an issue",
  "issue.restored": "restored an issue",
  "comment.created": "commented",
  "comment.updated": "edited a comment",
  "comment.deleted": "deleted a comment",
  "member.invited": "invited a member",
  "member.joined": "joined the organization",
  "member.role_changed": "changed a role",
  "member.removed": "removed a member",
  "billing.plan_changed": "changed the plan",
  "flag.toggled": "toggled a feature flag",
};

export function activityLabel(action: ActivityAction): string {
  return ACTIVITY_LABELS[action] ?? action;
}

/** The calendar day an event belongs to, in UTC (`YYYY-MM-DD`). */
export function activityDay(event: ActivityEvent): string {
  return event.occurredAt.slice(0, 10);
}

/**
 * Groups a flat event list into the day buckets `ActivityFeed` consumes,
 * newest day first and newest event first within a day.
 */
export function groupEventsByDay(
  events: readonly ActivityEvent[],
): readonly ActivityGroup[] {
  const byDay = new Map<string, ActivityEvent[]>();

  for (const event of events) {
    const day = activityDay(event);
    const bucket = byDay.get(day) ?? [];
    bucket.push(event);
    byDay.set(day, bucket);
  }

  return [...byDay.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([day, bucket]) => ({
      day,
      events: [...bucket].sort((a, b) =>
        b.occurredAt.localeCompare(a.occurredAt),
      ),
    }));
}

/**
 * The background job layer: the in-process queue, the scheduler's cadence and
 * the two jobs whose behaviour other layers depend on — the overdue scan that
 * feeds the notification fan-out, and the trial expiry that moves plans.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import {
  drain,
  enqueue,
  isSchedulerRunning,
  pendingCount,
  resetQueue,
  startScheduler,
  stopScheduler,
} from "@/server/jobs";
import { backoffMs } from "@/server/jobs/webhook-delivery-job";
import { shouldRunForOrg } from "@/server/jobs/digest-email-job";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
const detachers: Unsubscribe[] = [];

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("jobs");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
  resetQueue();
  stopScheduler();
});

afterAll(() => {
  cleanup();
});

describe("the in-process queue", () => {
  it("is idempotent on the job id", () => {
    const job = {
      id: "usage-rollup:1",
      kind: "usage-rollup" as const,
      runAt: toIsoTimestamp(NOW),
      attempts: 0,
      payload: {},
    };

    enqueue(job);
    enqueue(job);

    expect(pendingCount()).toBe(1);
  });

  it("leaves jobs scheduled in the future alone", async () => {
    enqueue({
      id: "usage-rollup:future",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(0);
    expect(pendingCount()).toBe(1);
  });

  it("runs a due job and removes it", async () => {
    enqueue({
      id: "usage-rollup:due",
      kind: "usage-rollup",
      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
      attempts: 0,
      payload: {},
    });

    await expect(drain()).resolves.toBe(1);
    expect(pendingCount()).toBe(0);
  });
});

describe("the scheduler", () => {
  it("reports whether it is running and stops cleanly", () => {
    expect(isSchedulerRunning()).toBe(false);
    startScheduler();
    expect(isSchedulerRunning()).toBe(true);
    stopScheduler();
    expect(isSchedulerRunning()).toBe(false);
  });
});

describe("the overdue scan", () => {
  it("emits issue.overdue for a past-due open issue, once", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late already",
        assigneeId: tenant.userIds.member,
        dueAt: PAST,
      }),
    );

    const seen: string[] = [];
    detachers.push(
      subscribe("issue.overdue", (payload) => {
        seen.push(payload.issueId);
      }),
    );

    const result = await runOverdueIssueJob(NOW);

    expect(seen).toEqual([issue.id]);
    expect(result.kind).toBe("overdue-issues");
    expect(result.processed).toBe(1);
    expect(result.failed).toBe(0);
  });

  it("ignores an overdue issue once it is archived", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but archived",
        dueAt: PAST,
      }),
    );
    await issueService.archiveIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });

  it("ignores an overdue issue once it is closed", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Late but done",
        dueAt: PAST,
      }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });

    const overdue = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );

    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
  });
});

describe("the usage rollup", () => {
  it("recounts the tenant's live rows", async () => {
    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBeGreaterThan(0);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const live = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });

    expect(usage.issuesUsed).toBe(live.total);
    expect(usage.seatsUsed).toBe(4);
  });
});

describe("pure job helpers", () => {
  it("backs delivery attempts off exponentially, with a ceiling", () => {
    expect(backoffMs(0)).toBe(0);
    expect(backoffMs(1)).toBe(1_000);
    expect(backoffMs(2)).toBe(2_000);
    expect(backoffMs(3)).toBe(4_000);
    expect(backoffMs(30)).toBe(300_000);
  });

  it("runs the digest only during the org's configured UTC hour", () => {
    const org = {
      ...tenant.org,
      settings: { ...tenant.org.settings, digestHourUtc: 7 },
    };

    expect(shouldRunForOrg(org, NOW)).toBe(true);
    expect(
      shouldRunForOrg(org, new Date("2026-06-01T08:00:00.000Z")),
    ).toBe(false);
    expect(
      shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
    ).toBe(false);
  });
});

/**
 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
 *
 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
 * prove a query is org-scoped. The database is `:memory:`, so nothing here
 * touches the developer's `data/taskflow.db`.
 */
// Aliased on import: the contract calls it `useInMemoryDb`, which the
// react-hooks lint rule would otherwise mistake for a React hook here.
import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { organizations } from "@/server/db/schema/organizations";
import { users } from "@/server/db/schema/users";
import type { Organization } from "@/types/organization";
import { makeOrganization, ORG_A, ORG_B } from "./factories";

let migrated = false;

/** Points the singleton client at an in-memory database and migrates it. */
export async function setupTestDb(): Promise<void> {
  attachInMemoryDb();
  await runMigrations(":memory:");
  migrated = true;
}

/** Truncates every table, keeping the schema — cheaper than re-migrating. */
export async function resetTestDb(): Promise<void> {
  if (!migrated) await setupTestDb();

  const db = getDb();
  const tables = db.$client
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
    )
    .all() as readonly { name: string }[];

  db.$client.pragma("foreign_keys = OFF");
  for (const table of tables) {
    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
  }
  db.$client.pragma("foreign_keys = ON");
}

/**
 * Inserts two organizations owned by two different users. Every "does this
 * query filter by orgId?" test seeds through here so the negative case is a
 * real row in a real other tenant, not an absence.
 */
export async function seedTwoTenants(): Promise<{
  orgA: Organization;
  orgB: Organization;
}> {
  const db = getDb();

  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
  const orgB = makeOrganization({
    id: ORG_B,
    name: "Globex",
    slug: "globex",
    ownerId: orgA.ownerId,
  });

  await db
    .insert(users)
    .values({
      id: orgA.ownerId,
      email: "owner@example.com",
      name: "Test Owner",
      passwordHash: "scrypt:00:00",
      timezone: "UTC",
      createdAt: orgA.createdAt,
      updatedAt: orgA.updatedAt,
    })
    .onConflictDoNothing();

  for (const org of [orgA, orgB]) {
    await db.insert(organizations).values({
      id: org.id,
      name: org.name,
      slug: org.slug,
      ownerId: org.ownerId,
      plan: org.plan,
      logoUrl: org.logoUrl,
      trialEndsAt: org.trialEndsAt,
      // `OrganizationSettings` is flattened across columns on this table.
      defaultIssueStatus: org.settings.defaultIssueStatus,
      allowPublicProjects: org.settings.allowPublicProjects,
      requireTwoFactor: org.settings.requireTwoFactor,
      digestHourUtc: org.settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
      archivedAt: org.archivedAt,
      createdAt: org.createdAt,
      updatedAt: org.updatedAt,
    });
  }

  return { orgA, orgB };
}

/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
