import { afterAll, beforeAll, describe, expect, it } from \"vitest\";
import { and, eq } from \"drizzle-orm\";
import { getDb, issues, comments, attachments, issueLabels, searchIndex, activityEvents } from \"@/server/db\";
import { RestoreRefusedError } from \"@/lib/soft-delete\";
import { runCleanupArchivedJob } from \"@/server/jobs/cleanup-archived-job\";
import * as issueRepo from \"@/server/repositories/issue-repository\";
import * as usageRepo from \"@/server/repositories/usage-repository\";
import * as attachmentService from \"@/server/services/attachment-service\";
import * as issueService from \"@/server/services/issue-service\";
import { registerActivityListeners } from \"@/server/services/activity-service\";
import { registerSearchListeners } from \"@/server/services/search-service\";
import { registerUsageListeners } from \"@/server/services/usage-service\";
import { createTenant, issueInput, useTemporaryDatabase } from \"./_support/fixtures\";
import type { Tenant } from \"./_support/fixtures\";

let cleanup: () => void;
let tenant: Tenant;
let detach: (() => void)[];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant(\"retention\", \"free\");
  detach = [registerActivityListeners(), registerSearchListeners(), registerUsageListeners()];
});

afterAll(() => {
  for (const off of detach) off();
  cleanup();
});

describe(\"issue trash\", () => {
  it(\"restores a live issue to usage, search and the audit log\", async () => {
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: \"Restore target\" }));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(0);
    const restored = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(issue.number);
    expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(1);
    expect(getDb().select().from(searchIndex).where(and(eq(searchIndex.subjectKind, \"issue\"), eq(searchIndex.subjectId, issue.id))).all()).toHaveLength(1);
    expect(getDb().select().from(activityEvents).where(and(eq(activityEvents.action, \"issue.restored\"), eq(activityEvents.subjectId, issue.id))).all()).toHaveLength(1);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id)).rejects.toMatchObject({ reason: \"not_archived\" });
  });

  it(\"purges all expired issues and dependents, returns storage, and retains number history\", async () => {
    const input = issueInput(tenant.org.id, tenant.project.id, { title: \"Expired target\" });
    const oldIds: string[] = [];
    for (let number = 2; number <= 106; number++) {
      const issue = await issueRepo.insertIssue(input, tenant.userIds.member, number);
      oldIds.push(issue.id);
    }
    const last = oldIds[oldIds.length - 1]"'!;
    const issue = (await issueRepo.findIssueById(tenant.org.id, last as typeof tenant.project.id & never))!;
    await attachmentService.addAttachment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, filename: "a.txt", contentType: "text/plain", sizeBytes: 1 });
    await attachmentService.addAttachment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, filename: "b.txt", contentType: "text/plain", sizeBytes: 1 });
    const db = getDb();
    const stamp = "2020-01-01T00:00:00.000Z";
    db.insert(comments).values({ id: "comment-retention", orgId: tenant.org.id, issueId: issue.id, authorId: tenant.userIds.member, body: "old comment", createdAt: stamp, updatedAt: stamp }).run();
    db.insert(issueLabels).values({ orgId: tenant.org.id, issueId: issue.id, labelId: "label-retention" }).run();
    db.insert(searchIndex).values({ id: "search-comment", orgId: tenant.org.id, subjectKind: "comment", subjectId: "comment-retention", content: "old comment", indexedAt: stamp }).run();
    db.insert(searchIndex).values({ id: "search-issue", orgId: tenant.org.id, subjectKind: "issue", subjectId: issue.id, content: "old issue", indexedAt: stamp }).run();
    for (const id of oldIds) db.update(issues).set({ archivedAt: stamp }).where(eq(issues.id, id)).run();
    await usageRepo.recomputeUsage(tenant.org.id);
    expect((await usageRepo.getUsage(tenant.org.id)).storageMbUsed).toBe(2);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id)).rejects.toBeInstanceOf(RestoreRefusedError);
    const result = await runCleanupArchivedJob(new Date());
    expect(result.failed).toBe(0);
    expect(result.processed).toBeGreaterThanOrEqual(105);
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toBeNull();
    expect(db.select().from(comments).where(eq(comments.issueId, issue.id)).all()).toHaveLength(0);
    expect(db.select().from(attachments).where(eq(attachments.issueId, issue.id)).all()).toHaveLength(0);
    expect(db.select().from(issueLabels).where(eq(issueLabels.issueId, issue.id)).all()).toHaveLength(0);
    expect(db.select().from(searchIndex).where(eq(searchIndex.subjectId, "comment-retention")).all()).toHaveLength(0);
    expect(db.select().from(searchIndex).where(eq(searchIndex.subjectId, issue.id)).all()).toHaveLength(0);
    const usage = await usageRepo.getUsage(tenant.org.id);
    expect(usage.storageMbUsed).toBe(0);
    expect(usage.issuesUsed).toBe(1);
    expect((await usageRepo.recomputeUsage(tenant.org.id)).storageMbUsed).toBe(usage.storageMbUsed);
    expect(await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id)).toBe(107);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id)).rejects.toMatchObject({ code: "not_found" });
  });
});
EOF
